/* Apple-style Single-Column Lead Form Redesign */
.apple-form {
  background-color: #F5F5F7;
  min-height: 100vh;
  padding-top: clamp(2rem, 4vw, 3.5rem);
  padding-bottom: clamp(3rem, 6vw, 6rem);
}

.apple-form .container-x {
  max-width: 680px;
  margin-left: auto;
  margin-right: auto;
  padding-left: clamp(1rem, 3vw, 1.5rem);
  padding-right: clamp(1rem, 3vw, 1.5rem);
}

.apple-form .paper {
  background: #FFFFFF;
  border-radius: 24px;
  padding: clamp(1.25rem, 4vw, 2.75rem);
  border: 1px solid rgba(0, 0, 0, 0.07);
  box-shadow: 0 4px 20px -2px rgba(15, 42, 91, 0.05), 0 20px 48px -12px rgba(15, 42, 91, 0.08);
}

.apple-form .section-title {
  font-family: 'Sora', -apple-system, BlinkMacSystemFont, sans-serif;
  font-weight: 600;
  letter-spacing: -0.03em;
  color: #1D1D1F;
  font-size: clamp(1.85rem, 4vw, 2.65rem);
  line-height: 1.15;
  margin-bottom: 0.5rem;
}

.apple-form .field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 0;
}

.apple-form .field label {
  font-family: 'Inter', sans-serif;
  font-size: 13px;
  font-weight: 500;
  color: #1D1D1F;
  letter-spacing: -0.01em;
}

.apple-form .field input,
.apple-form .field select,
.apple-form .field textarea {
  font-family: 'Inter', sans-serif;
  font-size: 16px;
  color: #1D1D1F;
  background: #FFFFFF;
  border: 1px solid rgba(0, 0, 0, 0.12);
  border-radius: 12px;
  height: 48px;
  padding: 0 14px;
  transition: border-color 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
  outline: none;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.02) inset;
}

.apple-form .field input:hover,
.apple-form .field select:hover {
  border-color: rgba(0, 0, 0, 0.25);
  background-color: #FAFAFC;
}

.apple-form .field input:focus,
.apple-form .field select:focus {
  border-color: #0071E3;
  box-shadow: 0 0 0 3.5px rgba(0, 113, 227, 0.18);
  background-color: #FFFFFF;
}

.apple-form .field select {
  appearance: none;
  background-image: url("data:image/svg+xml,%3Csvg width='10' height='6' viewBox='0 0 10 6' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1L5 5L9 1' stroke='%2386868B' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
  background-position: right 14px center;
  background-repeat: no-repeat;
  padding-right: 36px;
  cursor: pointer;
}

.apple-form .btn-primary {
  background: #0F2A5B;
  color: #FFFFFF;
  border: none;
  border-radius: 999px;
  min-height: 52px;
  padding: 14px 28px;
  font-family: 'Inter', sans-serif;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: -0.01em;
  box-shadow: 0 4px 14px rgba(15, 42, 91, 0.18);
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  width: 100%;
  justify-content: center;
}

.apple-form .btn-primary:hover:not(:disabled) {
  background: #143775;
  transform: translateY(-1px);
  box-shadow: 0 8px 24px rgba(15, 42, 91, 0.25);
}

.apple-form .btn-primary:active:not(:disabled) {
  transform: translateY(0);
  box-shadow: 0 2px 8px rgba(15, 42, 91, 0.15);
}
